// Módulo ES real, cargado con importación dinámica desde una data URL para
// poder mostrar export/import ejecutándose en un único fichero con Node
// (`node --input-type=module` o un fichero .mjs).
const moduleSource = "export const PI = 3.14; export function area(r) { return PI * r * r; } export default 'circulo';";
const mod = await import('data:text/javascript,' + encodeURIComponent(moduleSource));

console.log(mod.default);
console.log(mod.PI);
console.log(mod.area(2));
